import json,urllib.request
URL="http://loophole-sim:8000/mcp"
_id=[0]
sid=[None]
def post(payload):
    data=json.dumps(payload).encode()
    req=urllib.request.Request(URL,data=data,headers={"Content-Type":"application/json","Accept":"application/json, text/event-stream"})
    if sid[0]: req.add_header("Mcp-Session-Id",sid[0])
    r=urllib.request.urlopen(req,timeout=30)
    if r.headers.get("Mcp-Session-Id"): sid[0]=r.headers.get("Mcp-Session-Id")
    ct=r.headers.get("Content-Type","")
    body=r.read().decode()
    if "text/event-stream" in ct:
        out=[]
        for line in body.splitlines():
            if line.startswith("data:"):
                out.append(line[5:].strip())
        return [json.loads(x) for x in out if x]
    else:
        return json.loads(body)
def init():
    p={"jsonrpc":"2.0","id":next_id(),"method":"initialize","params":{"protocolVersion":"2024-11-05","capabilities":{},"clientInfo":{"name":"cli","version":"1"}}}
    res=post(p)
    post({"jsonrpc":"2.0","method":"notifications/initialized"})
    return res
def next_id():
    _id[0]+=1
    return _id[0]
def call(name,args=None):
    p={"jsonrpc":"2.0","id":next_id(),"method":"tools/call","params":{"name":name,"arguments":args or {}}}
    res=post(p)
    if isinstance(res,list): res=res[-1]
    return res
if __name__=="__main__":
    init()
    print(json.dumps(call("tools/list"),indent=1)[:3000])
