cd /tmp/opencode && cat > cli.py <<'EOF'
import json,sys,base64,hashlib
import mcpcli
mcpcli.init()
def do(name,args):
    r=mcpcli.call(name,args)
    res=r.get("result",r)
    content=res.get("content") if isinstance(res,dict) else None
    if content:
        out=[]
        for c in content:
            if c.get("type")=="text":
                try: out.append(json.loads(c["text"]))
                except: out.append(c["text"])
            elif c.get("type")=="image":
                d=base64.b64decode(c["data"])
                fn="/tmp/opencode/img_"+hashlib.md5(d).hexdigest()[:8]+"."+(c.get("mimeType","image/png").split("/")[1])
                open(fn,"wb").write(d); out.append({"saved":fn})
        return out
    return res
if __name__=="__main__":
    name=sys.argv[1]
    args=json.loads(sys.argv[2]) if len(sys.argv)>2 else {}
    print(json.dumps(do(name,args),indent=1))
